20	/*!
21	 * \file maca_device_api.cc
22	 * \brief GPU specific API
23	 */
24	#include <mcc/mcc_global.h>
25	#include <mcr/mc_runtime_api.h>
26	#include <mxc/mxc.h>
27	#include <tvm/ffi/extra/c_env_api.h>
