35	#include <cstring>
36	
37	#include "maca_common.h"
38	#include "tvm/ffi/base_details.h"
39	
40	namespace tvm {
41	namespace runtime {
42	
43	class MACADeviceAPI final : public DeviceAPI {
44	public:
45	  void SetDevice(Device dev) final { MACA_CALL(mcSetDevice(dev.device_id)); }
46	  void GetAttr(Device device, DeviceAttrKind kind, ffi::Any *rv) final {
47	    int value = 0;
48	    switch (kind) {
49	    case kExist: {
50	      int count;
51	      auto err = mcGetDeviceCount(&count);
52	      value = (err == mcSuccess && static_cast<int>(count > device.device_id));
53	      break;
54	    }
55	    case kMaxThreadsPerBlock: {
56	      MACA_CALL(mcDeviceGetAttribute(
57	          &value, mcDeviceAttributeMaxThreadsPerBlock, device.device_id));
58	      break;
59	    }
60	    case kWarpSize: {
61	      MACA_CALL(mcDeviceGetAttribute(&value, mcDeviceAttributeWarpSize,
62	                                     device.device_id));
63	      break;
64	    }
65	    case kMaxSharedMemoryPerBlock: {
66	      MACA_CALL(mcDeviceGetAttribute(
67	          &value, mcDeviceAttributeMaxSharedMemoryPerBlock, device.device_id));
68	      break;
69	    }
70	    case kComputeVersion: {
71	      std::ostringstream os;
72	      MACA_CALL(mcDeviceGetAttribute(
73	          &value, mcDeviceAttributeComputeCapabilityMajor, device.device_id));
74	      os << value << ".";
75	      MACA_CALL(mcDeviceGetAttribute(
76	          &value, mcDeviceAttributeComputeCapabilityMinor, device.device_id));
77	      os << value;
78	      *rv = os.str();
79	      return;
80	    }
81	    case kDeviceName: {
82	      std::string name(256, 0);
83	      MACA_CALL(mcDeviceGetName(&name[0], name.size(), device.device_id));
84	      name.resize(strlen(name.c_str()));
85	      *rv = std::move(name);
86	      return;
87	    }
88	    case kMaxClockRate: {
89	      MACA_CALL(mcDeviceGetAttribute(&value, mcDeviceAttributeClockRate,
90	                                     device.device_id));
91	      break;
92	    }
93	    case kMultiProcessorCount: {
94	      MACA_CALL(mcDeviceGetAttribute(
95	          &value, mcDeviceAttributeMultiProcessorCount, device.device_id));
96	      break;
97	    }
98	    case kMaxThreadDimensions: {
99	      int dims[3];
100	      MACA_CALL(mcDeviceGetAttribute(&dims[0], mcDeviceAttributeMaxBlockDimX,
101	                                     device.device_id));
102	      MACA_CALL(mcDeviceGetAttribute(&dims[1], mcDeviceAttributeMaxBlockDimY,
103	                                     device.device_id));
104	      MACA_CALL(mcDeviceGetAttribute(&dims[2], mcDeviceAttributeMaxBlockDimZ,
105	                                     device.device_id));
106	
107	      std::stringstream ss;
108	      ss << "[" << dims[0] << ", " << dims[1] << ", " << dims[2] << "]";
109	      *rv = ss.str();
110	      return;
111	    }
112	    case kMaxRegistersPerBlock:
113	      MACA_CALL(mcDeviceGetAttribute(
114	          &value, mcDeviceAttributeMaxRegistersPerBlock, device.device_id));
115	      break;
116	    case kGcnArch:
117	      return;
118	    case kApiVersion: {
119	      // *rv = MACA_VERSION;
120	      return;
121	    }
122	    case kDriverVersion:
123	      return;
124	    case kL2CacheSizeBytes: {
125	      // Get size of device l2 cache size in bytes.
126	      int l2_size;
127	      MACA_CALL(mcDeviceGetAttribute(&l2_size, mcDeviceAttributeL2CacheSize,
128	                                     device.device_id));
129	      *rv = l2_size;
130	      return;
131	    }
132	    case kTotalGlobalMemory: {
133	      mcDeviceProp_t prop;
134	      MACA_CALL(mcGetDeviceProperties(&prop, device.device_id));
135	      int64_t total_global_memory = prop.totalGlobalMem;
136	      *rv = total_global_memory;
137	      return;
138	    }
139	    case kAvailableGlobalMemory: {
140	      size_t free_mem, total_mem;
141	      MACA_CALL(mcMemGetInfo(&free_mem, &total_mem));
142	      *rv = static_cast<int64_t>(free_mem);
143	      return;
144	    }
145	    case kImagePitchAlignment:
146	      return;
147	    }
148	    *rv = value;
149	  }
150	  void *AllocDataSpace(Device dev, size_t nbytes, size_t alignment,
151	                       DLDataType type_hint) final {
152	    TVM_FFI_ICHECK_EQ(256 % alignment, 0U)
153	        << "MACA space is aligned at 256 bytes";
154	    void *ret;
155	    if (dev.device_type == kDLMACAHost) {
156	      VLOG(1) << "allocating " << nbytes << "bytes on host";
157	      MACA_CALL(mcMallocHost(&ret, nbytes));
158	    } else {
159	      MACA_CALL(mcSetDevice(dev.device_id));
160	      VLOG(1) << "allocating " << nbytes << " bytes on device";
161	      MACA_CALL(mcMalloc(&ret, nbytes));
162	    }
163	    return ret;
164	  }
165	
166	  void FreeDataSpace(Device dev, void *ptr) final {
167	    if (dev.device_type == kDLMACAHost) {
168	      MACA_CALL(mcFreeHost(ptr));
169	    } else {
170	      MACA_DRIVER_CALL(mcSetDevice(dev.device_id));
171	      MACA_DRIVER_CALL(mcFree(ptr));
172	    }
173	  }
174	
175	protected:
176	  void CopyDataFromTo(const void *from, size_t from_offset, void *to,
177	                      size_t to_offset, size_t size, Device dev_from,
178	                      Device dev_to, DLDataType type_hint,
179	                      TVMStreamHandle stream) final {
180	    mcStream_t maca_stream = static_cast<mcStream_t>(stream);
181	    from = static_cast<const char *>(from) + from_offset;
182	    to = static_cast<char *>(to) + to_offset;
183	    if (dev_from.device_type == kDLMACAHost) {
184	      dev_from.device_type = kDLCPU;
185	    }
186	    if (dev_to.device_type == kDLMACAHost) {
187	      dev_to.device_type = kDLCPU;
188	    }
189	
190	    if (dev_from.device_type == kDLMACA && dev_to.device_type == kDLMACA) {
191	      MACA_CALL(mcSetDevice(dev_from.device_id));
192	      if (dev_from.device_id == dev_to.device_id) {
193	        GPUCopy(from, to, size, mcMemcpyDeviceToDevice, maca_stream);
194	      } else {
195	        MACA_CALL(mcMemcpyPeerAsync(to, dev_to.device_id, from,
196	                                    dev_from.device_id, size, maca_stream));
197	      }
198	    } else if (dev_from.device_type == kDLMACA &&
199	               dev_to.device_type == kDLCPU) {
200	      MACA_CALL(mcSetDevice(dev_from.device_id));
201	      GPUCopy(from, to, size, mcMemcpyDeviceToHost, maca_stream);
202	    } else if (dev_from.device_type == kDLCPU &&
203	               dev_to.device_type == kDLMACA) {
204	      MACA_CALL(mcSetDevice(dev_to.device_id));
205	      GPUCopy(from, to, size, mcMemcpyHostToDevice, maca_stream);
206	    } else {
207	      LOG(FATAL) << "expect copy from/to GPU or between GPU";
208	    }
209	  }
210	
211	public:
212	  TVMStreamHandle CreateStream(Device dev) {
213	    MACA_CALL(mcSetDevice(dev.device_id));
214	    mcStream_t retval;
215	    MACA_CALL(mcStreamCreateWithFlags(&retval, mcStreamNonBlocking));
216	    return static_cast<TVMStreamHandle>(retval);
217	  }
218	
219	  void FreeStream(Device dev, TVMStreamHandle stream) {
220	    MACA_CALL(mcSetDevice(dev.device_id));
221	    mcStream_t mc_stream = static_cast<mcStream_t>(stream);
222	    MACA_CALL(mcStreamDestroy(mc_stream));
223	  }
224	
225	  void SyncStreamFromTo(Device dev, TVMStreamHandle event_src,
226	                        TVMStreamHandle event_dst) {
227	    MACA_CALL(mcSetDevice(dev.device_id));
228	    mcStream_t src_stream = static_cast<mcStream_t>(event_src);
229	    mcStream_t dst_stream = static_cast<mcStream_t>(event_dst);
230	    mcEvent_t evt;
231	    MACA_CALL(mcEventCreate(&evt));
232	    MACA_CALL(mcEventRecord(evt, src_stream));
233	    MACA_CALL(mcStreamWaitEvent(dst_stream, evt, 0));
234	    MACA_CALL(mcEventDestroy(evt));
235	  }
236	
237	  void StreamSync(Device dev, TVMStreamHandle stream) final {
238	    MACA_CALL(mcSetDevice(dev.device_id));
239	    MACA_CALL(mcStreamSynchronize(static_cast<mcStream_t>(stream)));
240	  }
241	
242	  void *AllocWorkspace(Device dev, size_t size, DLDataType type_hint) final {
243	    return MACAThreadEntry::ThreadLocal()->pool.AllocWorkspace(dev, size);
244	  }
245	
246	  void FreeWorkspace(Device dev, void *data) final {
247	    MACAThreadEntry::ThreadLocal()->pool.FreeWorkspace(dev, data);
248	  }
249	
250	  static MACADeviceAPI *Global() {
251	    static MACADeviceAPI *inst = new MACADeviceAPI();
252	    return inst;
253	  }
254	
255	private:
256	  static void GPUCopy(const void *from, void *to, size_t size,
257	                      mcMemcpyKind kind, mcStream_t stream) {
258	    MACA_CALL(mcMemcpyAsync(to, from, size, kind, stream));
259	  }
260	};
261	
262	MACAThreadEntry::MACAThreadEntry() : pool(kDLMACA, MACADeviceAPI::Global()) {}
263	
264	MACAThreadEntry *MACAThreadEntry::ThreadLocal() {
265	  static thread_local MACAThreadEntry inst;
266	  return &inst;
267	}
268	
269	TVM_FFI_STATIC_INIT_BLOCK() {
270	  namespace refl = tvm::ffi::reflection;
271	  refl::GlobalDef()
272	      .def_packed("device_api.maca",
273	                  [](ffi::PackedArgs args, ffi::Any *rv) {
274	                    DeviceAPI *ptr = MACADeviceAPI::Global();
275	                    *rv = static_cast<void *>(ptr);
276	                  })
277	      .def_packed("device_api.maca_host",
278	                  [](ffi::PackedArgs args, ffi::Any *rv) {
279	                    DeviceAPI *ptr = MACADeviceAPI::Global();
280	                    *rv = static_cast<void *>(ptr);
281	                  });
282	}
283	
284	class MACATimerNode : public TimerNode {
285	public:
286	  virtual void Start() {
287	    int device_id;
288	    MACA_CALL(mcGetDevice(&device_id));
289	    stream_ = TVMFFIEnvGetStream(kDLMACA, device_id);
290	    MACA_CALL(mcEventRecord(start_, static_cast<mcStream_t>(stream_)));
291	  }
292	  virtual void Stop() {
293	    MACA_CALL(mcEventRecord(stop_, static_cast<mcStream_t>(stream_)));
294	  }
295	  virtual int64_t SyncAndGetElapsedNanos() {
296	    MACA_CALL(mcEventSynchronize(stop_));
297	    float milliseconds = 0;
298	    MACA_CALL(mcEventElapsedTime(&milliseconds, start_, stop_));
299	    return milliseconds * 1e6;
300	  }
301	  virtual ~MACATimerNode() {
302	    MACA_CALL(mcEventDestroy(start_));
303	    MACA_CALL(mcEventDestroy(stop_));
304	  }
305	  MACATimerNode() {
306	    MACA_CALL(mcEventCreate(&start_));
307	    MACA_CALL(mcEventCreate(&stop_));
308	  }
309	
310	  TVM_FFI_DECLARE_OBJECT_INFO_FINAL("runtime.maca.MACATimerNode", MACATimerNode,
311	                                    TimerNode);
312	
313	private:
314	  mcEvent_t start_;
315	  mcEvent_t stop_;
316	  TVMStreamHandle stream_;
317	};
318	
319	TVM_FFI_STATIC_INIT_BLOCK() {
320	  namespace refl = tvm::ffi::reflection;
321	  refl::GlobalDef().def("profiling.timer.maca", [](Device dev) {
322	    return Timer(ffi::make_object<MACATimerNode>());
323	  });
324	}
325	} // namespace runtime
326	} // namespace tvm
