45	
46	inline void EnsureCurrentDeviceContext(int device_id) {
47	  // Driver API entry points require a current context on this thread.
48	  // `mcGetDevice` reports the logical device, but it does not guarantee the
49	  // primary context is bound.
50	  MACA_CALL(mcSetDevice(device_id));
51	}
52	
53	// Module to support thread-safe multi-GPU execution.
54	// mcModule_t is a per-GPU module
55	// The runtime will contain a per-device module table
56	// The modules will be lazily loaded
57	class MACAModuleNode : public ffi::ModuleObj {
58	public:
59	  explicit MACAModuleNode(std::string data, std::string fmt,
60	                          ffi::Map<ffi::String, FunctionInfo> fmap,
61	                          std::string maca_source)
62	      : data_(data), fmt_(fmt), fmap_(fmap), maca_source_(maca_source) {
63	    std::fill(module_.begin(), module_.end(), nullptr);
64	  }
65	  // destructor
66	  ~MACAModuleNode() {
67	    for (size_t i = 0; i < module_.size(); ++i) {
68	      if (module_[i] != nullptr) {
69	        MACA_CALL(mcSetDevice(static_cast<int>(i)));
70	        MACA_DRIVER_CALL(mcModuleUnload(module_[i]));
71	      }
72	    }
73	  }
74	
75	  const char *kind() const final { return "maca"; }
76	
77	  int GetPropertyMask() const final {
78	    return ffi::Module::kBinarySerializable | ffi::Module::kRunnable;
79	  }
80	  ffi::Optional<ffi::Function> GetFunction(const ffi::String &name) final;
81	
82	  ffi::Bytes SaveToBytes() const final {
83	    std::string buffer;
84	    support::BytesOutStream stream(&buffer);
85	    stream.Write(fmt_);
86	    stream.Write(fmap_);
87	    stream.Write(data_);
88	    return ffi::Bytes(std::move(buffer));
89	  }
90	
91	  ffi::String InspectSource(const ffi::String &format) const final {
92	    if (format == fmt_)
93	      return data_;
94	    if (maca_source_.length() != 0) {
95	      return maca_source_;
96	    } else {
97	      if (fmt_ == "fatbin")
98	        return data_;
99	      return "";
100	    }
101	  }
102	
103	  // get a mcfunction_t from primary context in device_id
104	  mcFunction_t GetFunc(int device_id, const std::string &func_name) {
105	    std::lock_guard<std::mutex> lock(mutex_);
106	    // must recheck under the lock scope
107	
108	    if (module_[device_id] == nullptr) {
109	      MACA_DRIVER_CALL(mcModuleLoadData(&(module_[device_id]), data_.c_str()));
110	    }
111	    mcFunction_t func;
112	    mcError_t result =
113	        mcModuleGetFunction(&func, module_[device_id], func_name.c_str());
114	    if (result != mcSuccess) {
115	      const char *msg = mcGetErrorName(result);
116	      TVM_FFI_THROW(MACAError) << "mcModuleGetFunction " << func_name
117	                               << " failed with error: " << msg;
118	    }
119	    return func;
120	  }
121	  // get a global var from primary context in device_id
122	  mcDeviceptr_t GetGlobal(int device_id, const std::string &global_name,
123	                          size_t expect_nbytes) {
124	    std::lock_guard<std::mutex> lock(mutex_);
125	    // must recheck under the lock scope
126	    if (module_[device_id] == nullptr) {
127	      MACA_DRIVER_CALL(mcModuleLoadData(&(module_[device_id]), data_.c_str()));
128	    }
129	    mcDeviceptr_t global = nullptr;
130	    size_t nbytes = 0;
131	
132	    MACA_DRIVER_CALL(mcModuleGetGlobal(&global, &nbytes, module_[device_id],
133	                                       global_name.c_str()));
134	    TVM_FFI_ICHECK_EQ(nbytes, expect_nbytes);
135	    return global;
136	  }
137	
138	private:
139	  // the binary data
140	  std::string data_;
141	  // The format
142	  std::string fmt_;
143	  // function information table.
144	  ffi::Map<ffi::String, FunctionInfo> fmap_;
145	  // The maca source.
146	  std::string maca_source_;
147	  // the internal modules per GPU, to be lazily initialized.
148	  std::array<mcModule_t, kMaxNumGPUs> module_;
149	  // internal mutex when updating the module
150	  std::mutex mutex_;
151	};
152	
153	// a wrapped function class to get packed func.
154	class MACAWrappedFunc {
155	public:
156	  // initialize the MACA function.
157	  void Init(MACAModuleNode *m, ffi::ObjectPtr<ffi::Object> sptr,
158	            const std::string &func_name, size_t num_void_args,
159	            const ffi::Array<ffi::String> &launch_param_tags) {
160	    m_ = m;
161	    sptr_ = sptr;
162	    func_name_ = func_name;
163	    std::fill(fcache_.begin(), fcache_.end(), nullptr);
164	    launch_param_config_.Init(num_void_args, launch_param_tags);
165	  }
166	  // invoke the function with void arguments
167	  void operator()(ffi::PackedArgs args, ffi::Any *rv, void *packed_args,
168	                  size_t packed_nbytes) const {
169	    int device_id;
170	    MACA_CALL(mcGetDevice(&device_id));
171	    EnsureCurrentDeviceContext(device_id);
172	    ThreadWorkLoad wl = launch_param_config_.Extract(args);
173	
174	    if (fcache_[device_id] == nullptr) {
175	      fcache_[device_id] = m_->GetFunc(device_id, func_name_);
176	    }
177	
178	    mcStream_t strm =
179	        static_cast<mcStream_t>(TVMFFIEnvGetStream(kDLMACA, device_id));
180	    mcError_t result;
181	
182	    TVM_FFI_ICHECK(wl.grid_dim(0) > 0 && wl.grid_dim(1) > 0 &&
183	                   wl.grid_dim(2) > 0)
184	        << "MACALaunch Error: grid dimension must be positive, but got"
185	        << " grid=(" << wl.grid_dim(0) << "," << wl.grid_dim(1) << ","
186	        << wl.grid_dim(2) << ")"
187	        << " in kernel " << func_name_
188	        << ". A zero grid dimension is often caused by a dynamic shape"
189	        << " (e.g. num_tokens) being 0 at runtime.";
190	
191	    mcGetLastError();
192	
193	    void *config[] = {MC_LAUNCH_PARAM_BUFFER_POINTER, packed_args,
194	                      MC_LAUNCH_PARAM_BUFFER_SIZE, &packed_nbytes,
195	                      MC_LAUNCH_PARAM_END};
196	    if (launch_param_config_.use_cooperative_launch()) {
197	      mcLaunchConfigExtension launch_config;
198	      launch_config.gridDimX = wl.grid_dim(0);
199	      launch_config.gridDimY = wl.grid_dim(1);
200	      launch_config.gridDimZ = wl.grid_dim(2);
201	      launch_config.blockDimX = wl.block_dim(0);
202	      launch_config.blockDimY = wl.block_dim(1);
203	      launch_config.blockDimZ = wl.block_dim(2);
204	      launch_config.sharedMemBytes = wl.dyn_shmem_size;
205	      launch_config.hStream = strm;
206	      mcLaunchAttribute attribute_ub[1];
207	      attribute_ub[0].id = mcLaunchAttributeCooperative;
208	      attribute_ub[0].val.cooperative = 1;
209	      launch_config.attrs = attribute_ub;
210	      launch_config.numAttrs = 1;
211	      result =
212	          mcModuleLaunchKernelEx(&launch_config, fcache_[device_id], nullptr,
213	                                 reinterpret_cast<void **>(&config));
214	    } else {
215	      // MACA supports only extra_args.
216	      result = mcModuleLaunchKernel(
217	          fcache_[device_id], wl.grid_dim(0), wl.grid_dim(1), wl.grid_dim(2),
218	          wl.block_dim(0), wl.block_dim(1), wl.block_dim(2), wl.dyn_shmem_size,
219	          strm, nullptr, reinterpret_cast<void **>(&config));
220	    }
221	
222	    if (result != mcSuccess && result != mcErrorDeinitialized) {
223	      const char *msg = mcGetErrorName(result);
224	      std::ostringstream os;
225	      os << "MACALaunch Error: " << msg << "\n"
226	         << " grid=(" << wl.grid_dim(0) << "," << wl.grid_dim(1) << ","
227	         << wl.grid_dim(2) << "), "
228	         << " block=(" << wl.block_dim(0) << "," << wl.block_dim(1) << ","
229	         << wl.block_dim(2) << ")"
230	         << " dyn_smem_bytes=" << wl.dyn_shmem_size;
231	      std::string maca = m_->InspectSource("");
232	      if (maca.length() != 0) {
233	        os << "// func_name=" << func_name_ << "\n"
234	           << "// MACA Source\n"
235	           << "// -----------\n"
236	           << maca;
237	      }
238	      TVM_FFI_THROW(InternalError) << os.str();
239	    }
240	
241	    // Check for asynchronous MACA errors that mcLaunchKernel's return value
242	    // does not capture (e.g. illegal memory access during kernel execution).
243	    // This matches the Cython backend's TILELANG_CHECK_LAST_ERROR macro.
244	    if (result == mcSuccess) {
245	      mcError_t last_err = mcPeekAtLastError();
246	      if (last_err != mcSuccess) {
247	        // Use driver API mcGetErrorName for the error name (mcGetErrorName
248	        // is not available in the macart stub).
249	        const char *err_name = mcGetErrorName(last_err);
250	        const char *err_str = mcGetErrorString(last_err);
251	        // Clear the sticky error so subsequent MACA calls are not poisoned.
252	        mcGetLastError();
253	        TVM_FFI_THROW(InternalError)
254	            << func_name_ << ": " << (err_name ? err_name : "unknown") << " - "
255	            << err_str;
256	      }
257	    }
258	  }
259	
260	private:
261	  // internal module
262	  MACAModuleNode *m_;
263	  // the resource holder
264	  ffi::ObjectPtr<ffi::Object> sptr_;
265	  // The name of the function.
266	  std::string func_name_;
267	  // Device function cache per device.
268	  // mark as mutable, to enable lazy initialization
269	  mutable std::array<mcFunction_t, kMaxNumGPUs> fcache_;
270	  // launch parameters configuration
271	  LaunchParamConfig launch_param_config_;
272	};
273	
274	ffi::Optional<ffi::Function>
275	MACAModuleNode::GetFunction(const ffi::String &name) {
276	  ffi::ObjectPtr<ffi::Object> sptr_to_self =
277	      ffi::GetObjectPtr<ffi::Object>(this);
278	  TVM_FFI_ICHECK_EQ(sptr_to_self.get(), this);
279	  auto opt_info = fmap_.Get(name);
280	  if (!opt_info.has_value())
281	    return ffi::Function();
282	  FunctionInfo info = opt_info.value();
283	  MACAWrappedFunc f;
284	  f.Init(this, sptr_to_self, name, info->arg_types.size(),
285	         info->launch_param_tags);
286	  return PackFuncPackedArgAligned(f, info->arg_types);
287	}
288	
289	ffi::Module MACAModuleCreate(std::string data, std::string fmt,
290	                             ffi::Map<ffi::String, FunctionInfo> fmap,
291	                             std::string maca_source) {
292	  auto n = ffi::make_object<MACAModuleNode>(data, fmt, fmap, maca_source);
293	  return ffi::Module(n);
294	}
295	
296	ffi::Module MACAModuleLoadFromBytes(const ffi::Bytes &bytes) {
297	  support::BytesInStream stream(bytes);
298	  std::string data;
299	  ffi::Map<ffi::String, FunctionInfo> fmap;
300	  std::string fmt;
301	  stream.Read(&fmt);
302	  TVM_FFI_ICHECK(stream.Read(&fmap));
303	  stream.Read(&data);
304	  return MACAModuleCreate(data, fmt, fmap, std::string());
